// Inverse kinematics solver for cobotta generated by yaik.
// Declare it next to yaik_rust_common.rs: `mod yaik_rust_common; mod cobotta_ik_generated;`
// Requires nalgebra, rand and glam in the host crate.
#![allow(non_snake_case, non_upper_case_globals, unused_variables, unused_mut, unused_parens, unused_labels, unused_imports, dead_code, clippy::all)]

use std::f64::consts::{E, PI};
use nalgebra::{DMatrix, Matrix4, SMatrix, Vector3};
use super::yaik_rust_common::*;

// Constants for solver
pub const ROBOT_NQ: usize = 6;
pub const MAX_N_SOLUTIONS: usize = 128;
pub const N_TREE_NODES: usize = 36;
pub const INTERMEDIATE_SOLUTION_SIZE: usize = 7;
pub const POSE_TOLERANCE: f64 = 1e-6;
pub const POSE_TOLERANCE_DEGENERATE: f64 = 1e-4;
pub const zero_tolerance: f64 = 1e-6;
pub type IkWorkspace = RawIkWorkspace<INTERMEDIATE_SOLUTION_SIZE, MAX_N_SOLUTIONS, ROBOT_NQ>;

// Robot parameters
pub const a_0: f64 = 710.0;
pub const d_1: f64 = -50.0;
pub const d_2: f64 = 590.0;
pub const d_3: f64 = 150.0;
pub const d_4: f64 = 85.0;
pub const post_transform_special_symbol_23: f64 = 75.0;
pub const pre_transform_special_symbol_13: f64 = 220.0;

// Unknown offsets from original unknown value to raw value
// Original value are the ones corresponded to robot (usually urdf/sdf)
// Raw value are the ones used in the solver
// unknown_i_raw = unknown_i_original + unknown_i_offset_original2raw
pub const th_0_offset_original2raw: f64 = 0.0;
pub const th_1_offset_original2raw: f64 = -1.5707963267948966;
pub const th_2_offset_original2raw: f64 = 0.0;
pub const th_3_offset_original2raw: f64 = 3.141592653589793;
pub const th_4_offset_original2raw: f64 = 3.141592653589793;
pub const th_5_offset_original2raw: f64 = -1.5707963267948966;

// The transformation between raw and original ee target
// Original value are the ones corresponded to robot (usually urdf/sdf)
// Raw value are the ones used in the solver
// ee_original = pre_transform * ee_raw * post_transform
// ee_raw = dh_forward_transform(theta_raw)
pub fn end_effector_target_original_to_raw(T_ee: &Matrix4<f64>) -> Matrix4<f64> {
    let r_11: f64 = T_ee[(0, 0)];
    let r_12: f64 = T_ee[(0, 1)];
    let r_13: f64 = T_ee[(0, 2)];
    let Px: f64 = T_ee[(0, 3)];
    let r_21: f64 = T_ee[(1, 0)];
    let r_22: f64 = T_ee[(1, 1)];
    let r_23: f64 = T_ee[(1, 2)];
    let Py: f64 = T_ee[(1, 3)];
    let r_31: f64 = T_ee[(2, 0)];
    let r_32: f64 = T_ee[(2, 1)];
    let r_33: f64 = T_ee[(2, 2)];
    let Pz: f64 = T_ee[(2, 3)];
    let mut ee_transformed = Matrix4::<f64>::identity();
    ee_transformed[(0, 0)] = 1.0*r_31;
    ee_transformed[(0, 1)] = 1.0*r_32;
    ee_transformed[(0, 2)] = 1.0*r_33;
    ee_transformed[(0, 3)] = 1.0*Pz - 1.0*post_transform_special_symbol_23*r_33;
    ee_transformed[(1, 0)] = 1.0*r_11;
    ee_transformed[(1, 1)] = 1.0*r_12;
    ee_transformed[(1, 2)] = 1.0*r_13;
    ee_transformed[(1, 3)] = 1.0*Px - 1.0*post_transform_special_symbol_23*r_13;
    ee_transformed[(2, 0)] = 1.0*r_21;
    ee_transformed[(2, 1)] = 1.0*r_22;
    ee_transformed[(2, 2)] = 1.0*r_23;
    ee_transformed[(2, 3)] = 1.0*Py - 1.0*post_transform_special_symbol_23*r_23 - 1.0*pre_transform_special_symbol_13;
    ee_transformed
}

pub fn end_effector_target_raw_to_original(T_ee: &Matrix4<f64>) -> Matrix4<f64> {
    let r_11: f64 = T_ee[(0, 0)];
    let r_12: f64 = T_ee[(0, 1)];
    let r_13: f64 = T_ee[(0, 2)];
    let Px: f64 = T_ee[(0, 3)];
    let r_21: f64 = T_ee[(1, 0)];
    let r_22: f64 = T_ee[(1, 1)];
    let r_23: f64 = T_ee[(1, 2)];
    let Py: f64 = T_ee[(1, 3)];
    let r_31: f64 = T_ee[(2, 0)];
    let r_32: f64 = T_ee[(2, 1)];
    let r_33: f64 = T_ee[(2, 2)];
    let Pz: f64 = T_ee[(2, 3)];
    let mut ee_transformed = Matrix4::<f64>::identity();
    ee_transformed[(0, 0)] = 1.0*r_21;
    ee_transformed[(0, 1)] = 1.0*r_22;
    ee_transformed[(0, 2)] = 1.0*r_23;
    ee_transformed[(0, 3)] = 1.0*Py + 1.0*post_transform_special_symbol_23*r_23;
    ee_transformed[(1, 0)] = 1.0*r_31;
    ee_transformed[(1, 1)] = 1.0*r_32;
    ee_transformed[(1, 2)] = 1.0*r_33;
    ee_transformed[(1, 3)] = 1.0*Pz + 1.0*post_transform_special_symbol_23*r_33 + 1.0*pre_transform_special_symbol_13;
    ee_transformed[(2, 0)] = 1.0*r_11;
    ee_transformed[(2, 1)] = 1.0*r_12;
    ee_transformed[(2, 2)] = 1.0*r_13;
    ee_transformed[(2, 3)] = 1.0*Px + 1.0*post_transform_special_symbol_23*r_13;
    ee_transformed
}

// ************* Below are the actual FK and IK implementations *******************

/// Forward kinematics of the original (urdf/sdf) joint values
pub fn compute_fk_matrix(theta_input_original: &[f64; ROBOT_NQ]) -> Matrix4<f64> {
    // Extract the variables
    let th_0: f64 = theta_input_original[0] + th_0_offset_original2raw;
    let th_1: f64 = theta_input_original[1] + th_1_offset_original2raw;
    let th_2: f64 = theta_input_original[2] + th_2_offset_original2raw;
    let th_3: f64 = theta_input_original[3] + th_3_offset_original2raw;
    let th_4: f64 = theta_input_original[4] + th_4_offset_original2raw;
    let th_5: f64 = theta_input_original[5] + th_5_offset_original2raw;

    // Temp variable for efficiency
    let x0: f64 = th_5.sin();
    let x1: f64 = th_0.sin();
    let x2: f64 = th_3.cos();
    let x3: f64 = th_3.sin();
    let x4: f64 = th_0.cos();
    let x5: f64 = th_1.sin();
    let x6: f64 = th_2.sin();
    let x7: f64 = x5*x6;
    let x8: f64 = th_1.cos();
    let x9: f64 = th_2.cos();
    let x10: f64 = -x4*x7 + x4*x8*x9;
    let x11: f64 = x1*x2 - x10*x3;
    let x12: f64 = th_5.cos();
    let x13: f64 = th_4.sin();
    let x14: f64 = x5*x9;
    let x15: f64 = x6*x8;
    let x16: f64 = -x14*x4 - x15*x4;
    let x17: f64 = th_4.cos();
    let x18: f64 = x1*x3 + x10*x2;
    let x19: f64 = -x13*x16 + x17*x18;
    let x20: f64 = -x13*x18 - x16*x17;
    let x21: f64 = a_0*x8;
    let x22: f64 = -x1*x7 + x1*x8*x9;
    let x23: f64 = -x2*x4 - x22*x3;
    let x24: f64 = -x1*x14 - x1*x15;
    let x25: f64 = x2*x22 - x3*x4;
    let x26: f64 = -x13*x24 + x17*x25;
    let x27: f64 = -x13*x25 - x17*x24;
    let x28: f64 = -x14 - x15;
    let x29: f64 = x28*x3;
    let x30: f64 = x7 - x8*x9;
    let x31: f64 = -x13*x30 + x17*x2*x28;
    let x32: f64 = -x13*x2*x28 - x17*x30;
    // End of temp variables
    let mut ee_pose_raw = Matrix4::<f64>::identity();
    ee_pose_raw[(0, 0)] = -x0*x11 + x12*x19;
    ee_pose_raw[(0, 1)] = -x0*x19 - x11*x12;
    ee_pose_raw[(0, 2)] = x20;
    ee_pose_raw[(0, 3)] = -d_1*x1 + d_2*x16 + d_3*x11 + d_4*x20 + x21*x4;
    ee_pose_raw[(1, 0)] = -x0*x23 + x12*x26;
    ee_pose_raw[(1, 1)] = -x0*x26 - x12*x23;
    ee_pose_raw[(1, 2)] = x27;
    ee_pose_raw[(1, 3)] = d_1*x4 + d_2*x24 + d_3*x23 + d_4*x27 + x1*x21;
    ee_pose_raw[(2, 0)] = x0*x29 + x12*x31;
    ee_pose_raw[(2, 1)] = -x0*x31 + x12*x28*x3;
    ee_pose_raw[(2, 2)] = x32;
    ee_pose_raw[(2, 3)] = -a_0*x5 + d_2*x30 - d_3*x29 + d_4*x32;
    end_effector_target_raw_to_original(&ee_pose_raw)
}

/// Forward kinematics returning any Pose4 type, e.g. nalgebra::Matrix4<f64> or glam::DMat4
pub fn compute_fk<P: Pose4>(theta_input_original: &[f64; ROBOT_NQ]) -> P {
    P::from_matrix4(&compute_fk_matrix(theta_input_original))
}

pub fn compute_twist_jacobian(theta_input_original: &[f64; ROBOT_NQ], jacobian: &mut SMatrix<f64, 6, ROBOT_NQ>) {
    // Extract the variables
    let th_0: f64 = theta_input_original[0] + th_0_offset_original2raw;
    let th_1: f64 = theta_input_original[1] + th_1_offset_original2raw;
    let th_2: f64 = theta_input_original[2] + th_2_offset_original2raw;
    let th_3: f64 = theta_input_original[3] + th_3_offset_original2raw;
    let th_4: f64 = theta_input_original[4] + th_4_offset_original2raw;
    let th_5: f64 = theta_input_original[5] + th_5_offset_original2raw;

    // Temp variable for efficiency
    let x0: f64 = th_0.cos();
    let x1: f64 = 1.0*x0;
    let x2: f64 = th_2.cos();
    let x3: f64 = th_1.sin();
    let x4: f64 = th_0.sin();
    let x5: f64 = 1.0*x4;
    let x6: f64 = x3*x5;
    let x7: f64 = th_2.sin();
    let x8: f64 = th_1.cos();
    let x9: f64 = x5*x8;
    let x10: f64 = -x2*x6 - x7*x9;
    let x11: f64 = th_3.cos();
    let x12: f64 = th_3.sin();
    let x13: f64 = 1.0*x2*x4*x8 - x6*x7;
    let x14: f64 = -x1*x11 - x12*x13;
    let x15: f64 = th_4.cos();
    let x16: f64 = th_4.sin();
    let x17: f64 = -x10*x15 - x16*(-x1*x12 + x11*x13);
    let x18: f64 = 1.0*x7;
    let x19: f64 = 1.0*x2;
    let x20: f64 = x18*x3 - x19*x8;
    let x21: f64 = -x18*x8 - x19*x3;
    let x22: f64 = x12*x21;
    let x23: f64 = -x11*x16*x21 - x15*x20;
    let x24: f64 = -x5;
    let x25: f64 = x1*x3;
    let x26: f64 = x1*x8;
    let x27: f64 = -x2*x25 - x26*x7;
    let x28: f64 = 1.0*x0*x2*x8 - x25*x7;
    let x29: f64 = 1.0*x11*x4 - x12*x28;
    let x30: f64 = -x15*x27 - x16*(x11*x28 + x12*x5);
    let x31: f64 = 1.0*a_0*x3;
    let x32: f64 = -pre_transform_special_symbol_13 + x31;
    let x33: f64 = -x32;
    let x34: f64 = d_2*x20 + pre_transform_special_symbol_13 - x31;
    let x35: f64 = a_0*x26 - d_1*x5;
    let x36: f64 = d_2*x27 + x35;
    let x37: f64 = d_3*x22;
    let x38: f64 = d_2*x20 - x32 - x37;
    let x39: f64 = d_3*x29 + x36;
    let x40: f64 = d_4*x23 + x34 - x37;
    let x41: f64 = d_4*x30 + x39;
    let x42: f64 = a_0*x9 + d_1*x1;
    let x43: f64 = d_2*x10 + x42;
    let x44: f64 = d_3*x14 + x43;
    let x45: f64 = d_4*x17 + x44;
    // End of temp variables

    jacobian.fill(0.0);
    jacobian[(0, 1)] = x1;
    jacobian[(0, 2)] = x1;
    jacobian[(0, 3)] = x10;
    jacobian[(0, 4)] = x14;
    jacobian[(0, 5)] = x17;
    jacobian[(1, 0)] = 1.00000000000000;
    jacobian[(1, 3)] = x20;
    jacobian[(1, 4)] = -x22;
    jacobian[(1, 5)] = x23;
    jacobian[(2, 1)] = x24;
    jacobian[(2, 2)] = x24;
    jacobian[(2, 3)] = x27;
    jacobian[(2, 4)] = x29;
    jacobian[(2, 5)] = x30;
    jacobian[(3, 1)] = -pre_transform_special_symbol_13*x5;
    jacobian[(3, 2)] = -x33*x5;
    jacobian[(3, 3)] = -x20*x36 + x27*x34;
    jacobian[(3, 4)] = x22*x39 + x29*x38;
    jacobian[(3, 5)] = -x23*x41 + x30*x40;
    jacobian[(4, 2)] = x1*x35 + x42*x5;
    jacobian[(4, 3)] = x10*x36 - x27*x43;
    jacobian[(4, 4)] = x14*x39 - x29*x44;
    jacobian[(4, 5)] = x17*x41 - x30*x45;
    jacobian[(5, 1)] = -pre_transform_special_symbol_13*x1;
    jacobian[(5, 2)] = -x1*x33;
    jacobian[(5, 3)] = -x10*x34 + x20*x43;
    jacobian[(5, 4)] = -x14*x38 - x22*x44;
    jacobian[(5, 5)] = -x17*x40 + x23*x45;
}

pub fn compute_angular_velocity_jacobian(theta_input_original: &[f64; ROBOT_NQ], jacobian: &mut SMatrix<f64, 3, ROBOT_NQ>) {
    // Extract the variables
    let th_0: f64 = theta_input_original[0] + th_0_offset_original2raw;
    let th_1: f64 = theta_input_original[1] + th_1_offset_original2raw;
    let th_2: f64 = theta_input_original[2] + th_2_offset_original2raw;
    let th_3: f64 = theta_input_original[3] + th_3_offset_original2raw;
    let th_4: f64 = theta_input_original[4] + th_4_offset_original2raw;
    let th_5: f64 = theta_input_original[5] + th_5_offset_original2raw;

    // Temp variable for efficiency
    let x0: f64 = th_0.cos();
    let x1: f64 = 1.0*x0;
    let x2: f64 = th_2.cos();
    let x3: f64 = th_1.sin();
    let x4: f64 = th_0.sin();
    let x5: f64 = 1.0*x4;
    let x6: f64 = x3*x5;
    let x7: f64 = th_2.sin();
    let x8: f64 = th_1.cos();
    let x9: f64 = -x2*x6 - x5*x7*x8;
    let x10: f64 = th_3.cos();
    let x11: f64 = th_3.sin();
    let x12: f64 = 1.0*x2*x4*x8 - x6*x7;
    let x13: f64 = th_4.cos();
    let x14: f64 = th_4.sin();
    let x15: f64 = 1.0*x7;
    let x16: f64 = 1.0*x2;
    let x17: f64 = x15*x3 - x16*x8;
    let x18: f64 = -x15*x8 - x16*x3;
    let x19: f64 = -x5;
    let x20: f64 = x1*x3;
    let x21: f64 = -x1*x7*x8 - x2*x20;
    let x22: f64 = 1.0*x0*x2*x8 - x20*x7;
    // End of temp variables

    jacobian.fill(0.0);
    jacobian[(0, 1)] = x1;
    jacobian[(0, 2)] = x1;
    jacobian[(0, 3)] = x9;
    jacobian[(0, 4)] = -x1*x10 - x11*x12;
    jacobian[(0, 5)] = -x13*x9 - x14*(-x1*x11 + x10*x12);
    jacobian[(1, 0)] = 1.00000000000000;
    jacobian[(1, 3)] = x17;
    jacobian[(1, 4)] = -x11*x18;
    jacobian[(1, 5)] = -x10*x14*x18 - x13*x17;
    jacobian[(2, 1)] = x19;
    jacobian[(2, 2)] = x19;
    jacobian[(2, 3)] = x21;
    jacobian[(2, 4)] = 1.0*x10*x4 - x11*x22;
    jacobian[(2, 5)] = -x13*x21 - x14*(x10*x22 + x11*x5);
}

pub fn compute_transform_point_jacobian(theta_input_original: &[f64; ROBOT_NQ], point_on_ee: &Vector3<f64>, jacobian: &mut SMatrix<f64, 3, ROBOT_NQ>) {
    // Extract the variables
    let th_0: f64 = theta_input_original[0] + th_0_offset_original2raw;
    let th_1: f64 = theta_input_original[1] + th_1_offset_original2raw;
    let th_2: f64 = theta_input_original[2] + th_2_offset_original2raw;
    let th_3: f64 = theta_input_original[3] + th_3_offset_original2raw;
    let th_4: f64 = theta_input_original[4] + th_4_offset_original2raw;
    let th_5: f64 = theta_input_original[5] + th_5_offset_original2raw;
    let p_on_ee_x: f64 = point_on_ee[0];
    let p_on_ee_y: f64 = point_on_ee[1];
    let p_on_ee_z: f64 = point_on_ee[2];

    // Temp variable for efficiency
    let x0: f64 = 1.0*p_on_ee_z;
    let x1: f64 = th_0.sin();
    let x2: f64 = 1.0*x1;
    let x3: f64 = p_on_ee_y*x2;
    let x4: f64 = th_1.sin();
    let x5: f64 = 1.0*x4;
    let x6: f64 = a_0*x5;
    let x7: f64 = -pre_transform_special_symbol_13 + x6;
    let x8: f64 = -x7;
    let x9: f64 = th_2.sin();
    let x10: f64 = x5*x9;
    let x11: f64 = th_2.cos();
    let x12: f64 = th_1.cos();
    let x13: f64 = 1.0*x12;
    let x14: f64 = x10 - x11*x13;
    let x15: f64 = th_0.cos();
    let x16: f64 = x11*x5;
    let x17: f64 = x13*x9;
    let x18: f64 = -x15*x16 - x15*x17;
    let x19: f64 = d_2*x14 + pre_transform_special_symbol_13 - x6;
    let x20: f64 = a_0*x13*x15 - d_1*x2;
    let x21: f64 = d_2*x18 + x20;
    let x22: f64 = th_3.sin();
    let x23: f64 = -x16 - x17;
    let x24: f64 = x22*x23;
    let x25: f64 = th_3.cos();
    let x26: f64 = -x10*x15 + 1.0*x11*x12*x15;
    let x27: f64 = 1.0*x1*x25 - x22*x26;
    let x28: f64 = d_3*x24;
    let x29: f64 = d_2*x14 - x28 - x7;
    let x30: f64 = d_3*x27 + x21;
    let x31: f64 = th_4.cos();
    let x32: f64 = th_4.sin();
    let x33: f64 = -x14*x31 - x23*x25*x32;
    let x34: f64 = -x18*x31 - x32*(x2*x22 + x25*x26);
    let x35: f64 = d_4*x33 + x19 - x28;
    let x36: f64 = d_4*x34 + x30;
    let x37: f64 = 1.0*p_on_ee_x;
    let x38: f64 = x0*x15 + x1*x37;
    let x39: f64 = 1.0*x15;
    let x40: f64 = x12*x2;
    let x41: f64 = a_0*x40 + d_1*x39;
    let x42: f64 = x2*x4;
    let x43: f64 = -x11*x42 - x40*x9;
    let x44: f64 = d_2*x43 + x41;
    let x45: f64 = 1.0*x1*x11*x12 - x42*x9;
    let x46: f64 = -x22*x45 - x25*x39;
    let x47: f64 = d_3*x46 + x44;
    let x48: f64 = -x31*x43 - x32*(-x22*x39 + x25*x45);
    let x49: f64 = d_4*x48 + x47;
    let x50: f64 = p_on_ee_y*x39;
    // End of temp variables

    jacobian.fill(0.0);
    jacobian[(0, 0)] = x0;
    jacobian[(0, 1)] = -pre_transform_special_symbol_13*x2 + x3;
    jacobian[(0, 2)] = -x2*x8 + x3;
    jacobian[(0, 3)] = -p_on_ee_y*x18 + p_on_ee_z*x14 - x14*x21 + x18*x19;
    jacobian[(0, 4)] = -p_on_ee_y*x27 - p_on_ee_z*x24 + x22*x23*x30 + x27*x29;
    jacobian[(0, 5)] = -p_on_ee_y*x34 + p_on_ee_z*x33 - x33*x36 + x34*x35;
    jacobian[(1, 1)] = -x38;
    jacobian[(1, 2)] = 1.0*x1*x41 + 1.0*x15*x20 - x38;
    jacobian[(1, 3)] = p_on_ee_x*x18 - p_on_ee_z*x43 - x18*x44 + x21*x43;
    jacobian[(1, 4)] = p_on_ee_x*x27 - p_on_ee_z*x46 - x27*x47 + x30*x46;
    jacobian[(1, 5)] = p_on_ee_x*x34 - p_on_ee_z*x48 - x34*x49 + x36*x48;
    jacobian[(2, 0)] = -x37;
    jacobian[(2, 1)] = -pre_transform_special_symbol_13*x39 + x50;
    jacobian[(2, 2)] = -x39*x8 + x50;
    jacobian[(2, 3)] = -p_on_ee_x*x14 + p_on_ee_y*x43 + x14*x44 - x19*x43;
    jacobian[(2, 4)] = p_on_ee_x*x24 + p_on_ee_y*x46 - x24*x47 - x29*x46;
    jacobian[(2, 5)] = -p_on_ee_x*x33 + p_on_ee_y*x48 + x33*x49 - x35*x48;
}

/// Raw ik on the raw end-effector target, appends the raw joint values to ik_output
